import json,ssl,base64,pathlib,urllib.request,datetime
q=pathlib.Path(__file__).parent;c=json.loads(pathlib.Path('/private/tmp/android-final-r9-entry/config.json').read_text());ctx=ssl.create_default_context(cadata=ssl.DER_cert_to_PEM_cert(base64.b64decode(c['certificate'])))
def get(actor,path):
 req=urllib.request.Request(c['origin']+'/api/v1/'+path,headers={'Authorization':'Bearer '+c['cases'][actor]['token']});return json.load(urllib.request.urlopen(req,context=ctx))
def meeting(file):return json.loads((q/file).read_text())['meeting']['id']
first=meeting('actual/declined--confirmed.interaction.json');feed=get('invite-owner','meetings/'+first+'/feed');(q/'first-decline-feed.json').write_text(json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'meetingId':first,'feed':feed},ensure_ascii=False,indent=2));entries=feed['entries'];assert not any(e['kind']=='participant_joined'for e in entries)
id=meeting('events/event--three-answers.interaction.json');f=get('invite-owner','meetings/'+id+'/feed');ev=[e for e in f['entries']if e['kind']in ['participant_joined','participant_left','rsvp_changed']];assert len(ev)==3;assert len(set(e['id']for e in ev))==3;assert {e['payload']['answer']for e in ev}=={'going','maybe','not_going'};(q/'system-event-verification.json').write_text(json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'meetingId':id,'events':ev,'distinctEventIds':3,'serverFeed':f},ensure_ascii=False,indent=2))
id=meeting('actual/invite--response-error-standard-phone.interaction.json');f=get('invite-owner','meetings/'+id+'/feed');ev=[e for e in f['entries']if e['kind']in ['participant_joined','participant_left','rsvp_changed']];assert len(ev)==1 and ev[0]['payload']['answer']=='maybe';(q/'error409-authority.json').write_text(json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'meetingId':id,'uiAttempt':'Going with oldrevision after second-deviceMaybe','serverEvents':ev,'noGoingCommitted':True},ensure_ascii=False,indent=2));print('API authority: first-decline nojoin, live3 distinctanswers, real409preservesMaybe')
